<script setup lang="ts">
import ShareSettings from './ShareSettings.vue';
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {api,labels,when,download} from './api';
import {marked} from 'marked';import DOMPurify from 'dompurify';
import Icon from './Icon.vue';
const props=defineProps<{item:any,projectId:string,requirements:any[],allItems:any[],canEdit:boolean,role:string}>();
const emit=defineEmits(['close','saved','error','notify','ai']);
const draft=ref<any>(JSON.parse(JSON.stringify(props.item))),tab=ref('content'),sideTab=ref('comments'),mode=ref(props.item.kind==='prototype'?'preview':'edit'),comments=ref<any[]>([]),revisions=ref<any[]>([]),comment=ref(''),busy=ref(false),error=ref(''),html=ref(''),frame=ref<HTMLIFrameElement>(),mobile=ref(false),shareUrl=ref(''),shareRole=ref('reviewer'),shareDays=ref(7),showShare=ref(false),revision=ref<any>(null),previewBusy=ref(false),importUrl=ref('');
const defaults:any={requirement:{description:'',status:'backlog',priority:'medium',module:'',release:'',assignee:'',dueDate:'',source:''},document:{type:'prd',content:'',requirementId:'',source:'',larkId:''},prototype:{language:'html',surface:'frontend',module:'',description:'',source:'',requirementId:''},template:{language:'html',category:'通用组件',description:'',source:''},release:{status:'planned',description:'',dueDate:'',requirementIds:[]}};
draft.value.body={...defaults[draft.value.kind],...draft.value.body};
const baseline=ref(JSON.stringify(draft.value));
const body=computed(()=>draft.value.body),isCode=computed(()=>['prototype','template'].includes(draft.value.kind));
const markdown=computed(()=>DOMPurify.sanitize(marked.parse(body.value.content||'') as string));
const titleText=computed(()=>({requirement:'需求详情',document:'产品文档',prototype:'原型工作室',template:'组件模板',release:'版本规划'} as any)[draft.value.kind]);
const dirty=computed(()=>JSON.stringify(draft.value)!==baseline.value);
function close(){if(dirty.value&&!confirm('有未保存的修改，确定关闭吗？'))return;emit('close');}
async function perform(fn:()=>Promise<any>){busy.value=true;error.value='';try{return await fn();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function loadMeta(){if(!draft.value.id)return;[comments.value,revisions.value]=await Promise.all([api(`/items/${draft.value.id}/comments`),api(`/items/${draft.value.id}/revisions`)]);}
async function save(){if(busy.value)return;if(!draft.value.title?.trim()){error.value='请先填写标题，再保存内容。';document.querySelector<HTMLInputElement>('.title-input')?.focus();return;}if(!props.projectId){error.value='请先选择所属项目';return;}return perform(async()=>{const data={kind:draft.value.kind,title:draft.value.title,body:body.value,version:draft.value.version};const result=await api(draft.value.id?'/items/'+draft.value.id:`/projects/${props.projectId}/items`,draft.value.id?'PATCH':'POST',data);draft.value=JSON.parse(JSON.stringify(result));baseline.value=JSON.stringify(draft.value);emit('saved',result);loadMeta().catch(()=>{});if(isCode.value&&body.value.source)await preview();return result;});}
async function preview(){if(!draft.value.id)return;previewBusy.value=true;try{const d=await api('/items/'+draft.value.id+'/preview');html.value=d.html;}catch(e:any){error.value=e.message;}finally{previewBusy.value=false;}}
async function bridge(e:MessageEvent){if(e.source!==frame.value?.contentWindow||e.data?.type!=='pm-data')return;const {requestId,...data}=e.data;try{const result=await api('/items/'+draft.value.id+'/data','POST',data);frame.value?.contentWindow?.postMessage({type:'pm-data-result',requestId,result},'*');}catch(e:any){frame.value?.contentWindow?.postMessage({type:'pm-data-result',requestId,error:e.message},'*');}}
async function sendComment(){await perform(async()=>{await api('/items/'+draft.value.id+'/comments','POST',{content:comment.value});comment.value='';await loadMeta();emit('notify','评审意见已提交');});}
async function share(){await perform(async()=>{const r=await api('/items/'+draft.value.id+'/shares','POST',{role:shareRole.value,days:Number(shareDays.value)});shareUrl.value=r.url;});}
async function copy(){try{await navigator.clipboard.writeText(shareUrl.value);emit('notify','分享链接已复制');}catch{const el=document.getElementById('share-link') as HTMLInputElement;el?.select();emit('notify','请复制已选中的链接');}}
async function useTemplate(t:any){body.value.source=t.body.source;body.value.language=t.body.language;mode.value='code';emit('notify','模板已应用，保存后可预览');}
async function saveTemplate(){await perform(async()=>{await api(`/projects/${props.projectId}/items`,'POST',{kind:'template',title:draft.value.title,body:{source:body.value.source,language:body.value.language,description:body.value.description||'',category:body.value.surface==='admin'?'后台组件':'前台组件'}});emit('notify','已保存到组件模板库');});}
function blankTemplate(type:string){body.value.language='html';body.value.source=type==='data'?`<!doctype html>
<html lang="zh-CN"><meta charset="UTF-8"><style>body{font:15px system-ui;padding:36px;background:#f8fafc;color:#253047}input,button{padding:12px;border:1px solid #ddd;border-radius:8px}button{background:#5b56e8;color:white;cursor:pointer}li{padding:14px;background:white;margin:10px 0;border-radius:8px}p{color:#667085}</style><h1>数据管理</h1><p>数据保存到当前原型的 MySQL 数据集合。</p><form id="form"><input id="name" placeholder="输入名称" required><button>添加记录</button></form><p id="message"></p><ul id="rows"></ul><script>
async function load(){try{const rows=await pmData('list','records');const root=document.getElementById('rows');root.replaceChildren();if(!rows.length)document.getElementById('message').textContent='还没有记录，添加第一条真实数据。';else document.getElementById('message').textContent='共 '+rows.length+' 条记录';for(const row of rows){const li=document.createElement('li');li.textContent=row.data.name;root.append(li)}}catch(e){document.getElementById('message').textContent=e.message}}document.getElementById('form').onsubmit=async e=>{e.preventDefault();try{await pmData('create','records',{name:document.getElementById('name').value});document.getElementById('name').value='';await load()}catch(e){document.getElementById('message').textContent=e.message}};load();
<\/script></html>`:`<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><style>*{box-sizing:border-box}body{margin:0;font:15px system-ui;background:#f7f8fb;color:#253047}nav{padding:22px 32px;background:white;border-bottom:1px solid #e8eaf0;display:flex;justify-content:space-between}main{padding:40px;max-width:960px;margin:auto}section{padding:32px;background:white;border:1px solid #e8eaf0;border-radius:14px}button{background:#5b56e8;border:0;color:white;padding:12px 20px;border-radius:8px;cursor:pointer}p{color:#778194}</style><nav><strong>产品名称</strong><span>工作台</span></nav><main><h1>页面标题</h1><section><h2>内容模块</h2><p>在源码中配置你的业务内容和交互。</p><button onclick="document.getElementById('status').textContent='操作已触发，请绑定业务逻辑'">主要操作</button><p id="status" role="status"></p></section></main></html>`;mode.value='code';}
async function startAI(kind:string){if(dirty.value){const saved=await save();if(!saved)return;}emit('ai',{kind,id:draft.value.id});}
function keyboard(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(props.canEdit)save();}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue='';}}
onMounted(async()=>{window.addEventListener('keydown',keyboard);window.addEventListener('message',bridge);window.addEventListener('beforeunload',beforeUnload);await perform(loadMeta);if(isCode.value&&body.value.source)await preview();});
onUnmounted(()=>{window.removeEventListener('keydown',keyboard);window.removeEventListener('message',bridge);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template><div class="modal-backdrop editor-backdrop"><section class="modal editor-modal" role="dialog" aria-modal="true" :aria-label="titleText"><header class="editor-header"><div class="editor-heading"><span class="project-icon small"><Icon :name="isCode?'PanelsTopLeft':draft.kind==='requirement'?'ListTodo':'FileText'"/></span><div><h3>{{titleText}}</h3><small>{{draft.id?'v'+draft.version+' · '+when(draft.updated_at):'尚未保存'}}<span v-if="dirty"> · 有未保存修改</span></small></div></div><div class="editor-actions"><button v-if="draft.id&&['prototype','document','template'].includes(draft.kind)" class="secondary" @click="download(draft)"><Icon name="Download" :size="15"/>导出</button><button v-if="draft.id&&role==='owner'&&['prototype','document'].includes(draft.kind)" class="secondary" @click="showShare=!showShare"><Icon name="Share2" :size="15"/>分享</button><button v-if="canEdit" class="primary" @click="save" :disabled="busy"><Icon name="Save" :size="15"/>{{busy?'保存中…':draft.id?'保存修改':'创建并保存'}}</button><button class="icon-button" @click="close" title="关闭编辑器"><Icon name="X"/></button></div></header><div v-if="error" class="error-banner" role="alert"><Icon name="AlertCircle"/><span>{{error}}</span><button class="icon-button" @click="error=''" title="关闭错误"><Icon name="X"/></button></div>
<ShareSettings v-if="showShare" :item-id="draft.id"/>
<div class="editor-layout"><div class="editor-main"><p class="editor-save-hint">标题必填 · Ctrl / ⌘ + S 保存 · 修改自动记录版本</p><input class="title-input" v-model="draft.title" placeholder="填写标题（必填）" maxlength="180" :disabled="!canEdit" aria-label="内容标题"/>
<template v-if="draft.kind==='requirement'"><div class="form-grid"><label>需求状态<select v-model="body.status" :disabled="!canEdit"><option v-for="s in ['backlog','planned','progress','review','done']" :value="s">{{labels[s]}}</option></select></label><label>优先级<select v-model="body.priority" :disabled="!canEdit"><option v-for="s in ['high','medium','low']" :value="s">{{labels[s]}}</option></select></label><label>所属模块<input v-model="body.module" placeholder="模块名称" :disabled="!canEdit"/></label><label>规划版本<input v-model="body.release" placeholder="例如：V1.0.1" :disabled="!canEdit"/></label><label>负责人<input v-model="body.assignee" placeholder="填写负责人" :disabled="!canEdit"/></label><label>期望完成日期<input v-model="body.dueDate" type="date" :disabled="!canEdit"/></label></div><label>需求描述<textarea v-model="body.description" rows="10" placeholder="描述背景、用户目标、功能规则与验收标准…" :disabled="!canEdit"/></label><label>需求来源<input v-model="body.source" placeholder="用户反馈、会议记录或文档链接" :disabled="!canEdit"/></label><div class="editor-ai-call" v-if="draft.id&&canEdit"><Icon name="Sparkles"/><div><strong>让需求再清晰一步</strong><small>以这条需求为上下文，生成 PRD 或交互原型。</small></div><button class="secondary" @click="startAI('prd')">AI 编写 PRD</button><button class="secondary" @click="startAI('prototype')">AI 生成原型</button></div></template>
<template v-if="draft.kind==='document'"><div class="document-toolbar"><select v-model="body.type" :disabled="!canEdit" aria-label="文档类型"><option value="prd">需求文档 PRD</option><option value="technical">技术文档</option><option value="note">产品笔记</option></select><select v-model="body.requirementId" :disabled="!canEdit" aria-label="关联需求"><option value="">不关联需求</option><option v-for="r in requirements" :value="r.id">{{r.title}}</option></select><div class="view-switch"><button :class="{active:mode==='edit'}" @click="mode='edit'">编辑</button><button :class="{active:mode==='preview'}" @click="mode='preview'">预览</button></div></div><textarea v-if="mode==='edit'" class="document-editor" v-model="body.content" :disabled="!canEdit" placeholder="# 产品需求文档&#10;&#10;## 背景与目标&#10;写下产品思考，或使用 AI 生成标准 PRD…" aria-label="文档正文"/><div v-else class="markdown-body" v-html="markdown"></div><div class="editor-footer-tools"><button v-if="draft.id&&canEdit" class="text-button accent" @click="startAI(body.type)"><Icon name="Sparkles" :size="16"/>AI 协作修改</button><button v-if="draft.id&&canEdit" class="text-button" :disabled="busy" @click="perform(async()=>{const d=await api('/items/'+draft.id+'/lark/export','POST',{});emit('notify','已创建 Lark 文档：'+d.documentId)})"><Icon name="ExternalLink" :size="15"/>导出为 Lark 文档</button><small v-if="body.larkId">Lark ID：{{body.larkId}}</small></div></template>
<template v-if="isCode"><div class="form-grid"><label>开发语言<select v-model="body.language" :disabled="!canEdit"><option value="html">HTML / CSS / JavaScript</option><option value="vue">Vue 单文件组件</option><option value="react">React / TSX</option></select></label><label v-if="draft.kind==='prototype'">原型端<select v-model="body.surface" :disabled="!canEdit"><option value="frontend">前台原型</option><option value="admin">后台原型</option></select></label><label v-else>组件分类<input v-model="body.category" :disabled="!canEdit"/></label><label v-if="draft.kind==='prototype'">所属模块<input v-model="body.module" :disabled="!canEdit" placeholder="例如：用户中心"/></label><label v-if="draft.kind==='prototype'">关联需求<select v-model="body.requirementId" :disabled="!canEdit"><option value="">不关联需求</option><option v-for="r in requirements" :value="r.id">{{r.title}}</option></select></label></div><label>模块说明与交互规则<textarea v-model="body.description" rows="2" :disabled="!canEdit" placeholder="描述页面用途、流程和验收重点…"/></label><div class="prototype-toolbar"><div class="view-switch"><button :class="{active:mode==='code'}" @click="mode='code'"><Icon name="Code2" :size="15"/>源码</button><button :class="{active:mode==='preview'}" @click="mode='preview';preview()"><Icon name="Eye" :size="15"/>预览已保存版本</button><button :class="{active:mode==='templates'}" @click="mode='templates'">使用模板</button></div><div class="inline"><button class="icon-button" @click="mobile=!mobile" title="切换桌面/移动尺寸"><Icon :name="mobile?'Smartphone':'Monitor'" :size="17"/></button><button v-if="draft.id" class="icon-button" title="全屏演示" @click="frame?.requestFullscreen()"><Icon name="Maximize2" :size="17"/></button></div></div><textarea v-if="mode==='code'" class="code-editor" v-model="body.source" :disabled="!canEdit" placeholder="输入原型源码，或从标准件开始…" aria-label="原型源码" spellcheck="false"/><div v-else-if="mode==='templates'" class="template-choices"><template v-if="canEdit"><button @click="blankTemplate('navigation')"><Icon name="PanelsTopLeft"/><strong>页面与导航框架</strong><span>基础布局 · HTML</span></button><button @click="blankTemplate('data')"><Icon name="Database"/><strong>数据管理标准件</strong><span>连接真实 MySQL 数据</span></button><button v-for="t in allItems.filter(i=>i.kind==='template')" @click="useTemplate(t)"><Icon name="Blocks"/><strong>{{t.title}}</strong><span>{{t.body.category}} · {{labels[t.body.language]}}</span></button></template><p v-else class="muted">编辑成员可以使用组件模板。</p></div><div v-else class="preview-stage"><div v-if="previewBusy" class="empty-state"><Icon name="LoaderCircle" class="spin"/>正在编译预览…</div><iframe v-else-if="html" ref="frame" :src="`/api/items/${draft.id}/render?v=${draft.version}`" sandbox="allow-scripts allow-forms" :class="{phone:mobile}" title="交互原型预览"/><div class="empty-state" v-else><Icon name="PanelsTopLeft" :size="36"/><h3>原型，从这里成形</h3><p>编写源码或选用模板，保存后即可交互预览。</p><button class="secondary" @click="mode='templates'">选择标准件</button></div></div><div class="editor-footer-tools"><span class="muted"><Icon name="Shield" :size="13"/>隔离运行 · 数据按原型独立保存</span><button v-if="canEdit&&draft.id" class="text-button accent" @click="startAI('prototype')"><Icon name="Sparkles" :size="15"/>AI 修改</button><button v-if="canEdit&&draft.kind==='prototype'&&body.source" class="text-button" @click="saveTemplate">存为模板</button></div></template>
<template v-if="draft.kind==='release'"><div class="form-grid"><label>迭代状态<select v-model="body.status" :disabled="!canEdit"><option v-for="s in ['planned','progress','released']" :value="s">{{labels[s]}}</option></select></label><label>计划发布日期<input type="date" v-model="body.dueDate" :disabled="!canEdit"/></label></div><label>版本目标 / 发布说明<textarea v-model="body.description" rows="5" :disabled="!canEdit" placeholder="这次迭代要实现什么目标？"/></label><h3>纳入此版本的需求</h3><div class="release-requirements"><label v-for="r in requirements" class="check-label"><input type="checkbox" :value="r.id" v-model="body.requirementIds" :disabled="!canEdit"/><span>{{r.title}}</span><small>{{labels[r.body.status]}}</small></label></div><p class="muted">发布时自动保存关联需求快照；后续修改不会改变已保存的历史版本。</p><details v-if="body.snapshot?.length"><summary>已发布的需求快照（{{body.snapshot.length}}）</summary><article v-for="s in body.snapshot"><h4>{{s.title}} · v{{s.version}}</h4><p>{{s.body.description}}</p></article></details></template>
</div><aside class="editor-side"><div class="filter-tabs"><button :class="{selected:sideTab==='comments'}" @click="sideTab='comments'"><Icon name="MessageSquare" :size="15"/>评审 <span>{{comments.length}}</span></button><button :class="{selected:sideTab==='history'}" @click="sideTab='history'"><Icon name="History" :size="15"/>版本</button></div><template v-if="sideTab==='comments'"><div class="comment-list"><div class="empty-mini" v-if="!comments.length"><Icon name="MessageSquare" :size="25"/><p>把意见留在上下文里，<br>让每次沟通都有回应。</p></div><article v-for="c in comments" class="comment-card"><div><strong>{{c.author}}</strong><span v-if="c.resolved" class="badge green">已解决</span></div><p>{{c.content}}</p><footer><small>{{when(c.created_at)}}</small><button v-if="canEdit" class="text-button" @click="perform(async()=>{await api('/comments/'+c.id,'PATCH',{resolved:!c.resolved});await loadMeta()})">{{c.resolved?'重新打开':'标记解决'}}</button></footer></article></div><form v-if="draft.id&&role!=='viewer'" class="comment-form" @submit.prevent="sendComment"><textarea v-model="comment" placeholder="提出建议或记录问题…" rows="3" required maxlength="10000"/><button class="primary" :disabled="busy||!comment.trim()"><Icon name="Send" :size="14"/>提交意见</button></form><p v-else class="empty-mini">{{draft.id?'当前为只读权限':'保存后即可邀请团队评审'}}</p></template><template v-else><div class="revision-list"><button v-for="r in revisions" :class="{selected:revision?.id===r.id}" @click="revision=r"><span class="revision-icon"><Icon name="GitBranch" :size="16"/></span><div><strong>版本 {{r.version}} <small v-if="r.version===draft.version">当前版本</small></strong><small>{{r.name}} · {{when(r.created_at)}}</small></div></button></div><div v-if="revision" class="revision-detail"><h4>{{revision.title}}</h4><pre>{{revision.body.content||revision.body.source||JSON.stringify(revision.body,null,2)}}</pre><button v-if="canEdit" class="secondary" @click="draft.title=revision.title;draft.body=JSON.parse(JSON.stringify(revision.body));emit('notify','历史内容已载入编辑器，保存后形成新版本')">载入此版本</button></div></template></aside></div></section></div></template>
